SELECT event_type, CASE WHEN duration_sec >= 532 THEN 'high' WHEN duration_sec >= 181 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, MONTH(event_time) AS event_month, COUNT(DISTINCT duration_sec) AS unique_event_types, SUM(CASE WHEN page = '/cart' THEN duration_sec ELSE 0 END) AS cart_duration_sec, AVG(duration_sec) AS avg_duration_sec FROM web_events GROUP BY event_type, CASE WHEN duration_sec >= 532 THEN 'high' WHEN duration_sec >= 181 THEN 'mid' ELSE 'low' END, MONTH(event_time);
